"""SOL 領域の幾何 (tsgeo.f)。SOL にずれ・傾き (DX DY DPX DPY) があるとき、LINE["S"|"GX"|"GZ"|"GCHI2"|"GCHI3", k] は領域内の軌道に沿って決まる。参照は SAD K64 (gs) の出力。
sg2: GEO が始端の SOL (前向き)、回転四極 K1>0・領域内の SOL を含む。sg3: GEO が終端の SOL (後ろ向き)、K1<0。"""
import io
import re

import pytest

SRC = {}
REF = {}
SRC['sg2'] = r'''MOMENTUM = 3GEV;
DRIFT D1 = (L=1) D2 = (L=0.5) D3 = (L=0.25);
QUAD QF = (L=0.3 K1=0.7) QD = (L=0.3 K1=-0.6) QS = (L=0.2 K1=0.05 ROTATE=0.3);
BEND B = (L=1.2 ANGLE=0.2617993877991494 E1=0.1308996938995747 E2=0.1308996938995747);
SOL SA = (L=0 BZ=2 BOUND=1 GEO=1 DX=2e-3 DY=-1e-3 DPX=3e-3 DPY=2e-3) SM = (L=0 BZ=0.8) SB = (L=0 BZ=0 BOUND=1);
MARK ST = ();
LINE CELLS = (QF D2 B D2 QD D3 SA D3 QS D3 SM D3 SB D3 B D2);
LINE RING = (ST CELLS);
FFS;
$FORM="16.10";
USE RING;
INS; CALC;
Do[Print["G ", k, " ", LINE["S",k], " ", LINE["GX",k], " ", LINE["GZ",k], " ", LINE["GCHI2",k], " ", LINE["GCHI3",k]], {k, 1, 18}];
Exit;
'''
REF['sg2'] = ['G     1.0000000000      .0000000000      .0000000000      .0000000000      .0000000000      .0000000000', 'G     2.0000000000      .0000000000      .0000000000      .0000000000      .0000000000      .0000000000', 'G     3.0000000000      .3000000000      .3000000000      .0000000000      .0000000000      .0000000000', 'G     4.0000000000      .8000000000      .8000000000      .0000000000      .0000000000      .0000000000', 'G     5.0000000000     2.0000000000     1.9863391154      .0000000000      .0000000000      .0000000000', 'G     6.0000000000     2.5000000000     2.4693020285      .0000000000      .0000000000      .0000000000', 'G     7.0000000000     2.8000000000     2.7590797764      .0000000000      .0000000000      .0000000000', 'G     8.0000000000     3.0500000000     3.0005612330      .0000000000      .0000000000      .0000000000', 'G     9.0000000000     3.0500000000     3.0000474609     -.0010000100     -.0019999910  5.9999989999E-6', 'G    10.0000000000     3.3000018061     3.2417214618     -.0015000074     -.0019999910  5.9999989999E-6', 'G    11.0000000000     3.5000032879     3.4350606626     -.0019000053     -.0019999910  5.9999989999E-6', 'G    12.0000000000     3.7500051874     3.6767346635     -.0024000028     -.0019999910  5.9999989999E-6', 'G    13.0000000000     3.7500051874     3.6767346635     -.0024000028     -.0019999910  5.9999989999E-6', 'G    14.0000000000     4.0000069730     3.9184086645     -.0029000002     -.0019999910  5.9999989999E-6', 'G    15.0000000000     4.0000069730     3.9181234765  -5.929715164E-5  -2.168560925E-4  1.058791209E-22', 'G    16.0000000000     4.2500069730     4.1595892090  -1.135111743E-4  -2.168560925E-4  1.058791209E-22', 'G    17.0000000000     5.4500069730     5.2649700274  -3.707760373E-4  -2.094669002E-4  -5.612648761E-5', 'G    18.0000000000     5.9500069730     5.6979220019  -4.755094866E-4  -2.094669002E-4  -5.612648761E-5']
SRC['sg3'] = r'''MOMENTUM = 3GEV;
DRIFT D1 = (L=1) D2 = (L=0.5) D3 = (L=0.25);
QUAD QF = (L=0.3 K1=0.7) QD = (L=0.3 K1=-0.6) QS = (L=0.2 K1=-0.05 ROTATE=0.3);
BEND B = (L=1.2 ANGLE=0.2617993877991494 E1=0.1308996938995747 E2=0.1308996938995747);
SOL SA = (L=0 BZ=2 BOUND=1) SM = (L=0 BZ=0.8) SB = (L=0 BZ=0 BOUND=1 GEO=1 DX=1e-3 DY=2e-3 DPX=-2e-3 DPY=1e-3);
MARK ST = ();
LINE CELLS = (QF D2 B D2 QD D3 SA D3 QS D3 SM D3 SB D3 B D2);
LINE RING = (ST CELLS);
FFS;
$FORM="16.10";
USE RING;
INS; CALC;
Do[Print["G ", k, " ", LINE["S",k], " ", LINE["GX",k], " ", LINE["GZ",k], " ", LINE["GCHI2",k], " ", LINE["GCHI3",k]], {k, 1, 18}];
Exit;
'''
REF['sg3'] = ['G     1.0000000000      .0000000000      .0000000000      .0000000000      .0000000000      .0000000000', 'G     2.0000000000      .0000000000      .0000000000      .0000000000      .0000000000      .0000000000', 'G     3.0000000000      .3000000000      .3000000000      .0000000000      .0000000000      .0000000000', 'G     4.0000000000      .8000000000      .8000000000      .0000000000      .0000000000      .0000000000', 'G     5.0000000000     2.0000000000     1.9863391154      .0000000000      .0000000000      .0000000000', 'G     6.0000000000     2.5000000000     2.4693020285      .0000000000      .0000000000      .0000000000', 'G     7.0000000000     2.8000000000     2.7590797764      .0000000000      .0000000000      .0000000000', 'G     8.0000000000     3.0500000000     3.0005612330      .0000000000      .0000000000      .0000000000', 'G     9.0000000000     3.0500000000     3.0008660920      .0028266578  -7.178415915E-4  -1.435685341E-6', 'G    10.0000000000     3.3000007870     3.2422075889      .0026471974  -7.178415915E-4  -1.435685341E-6', 'G    11.0000000000     3.5000014029     3.4352807864      .0025036291  -7.178415915E-4  -1.435685341E-6', 'G    12.0000000000     3.7500021594     3.6766222832      .0023241687  -7.178415915E-4  -1.435685341E-6', 'G    13.0000000000     3.7500021594     3.6766222832      .0023241687  -7.178415915E-4  -1.435685341E-6', 'G    14.0000000000     4.0000028353     3.9179637801      .0021447083  -7.178415915E-4  -1.435685341E-6', 'G    15.0000000000     4.0000028353     3.9182232919  1.4470739836E-4  2.8215697277E-4  3.087863603E-15', 'G    16.0000000000     4.2500028353     4.1596948078  2.1524664061E-4  2.8215697277E-4  3.087863603E-15', 'G    17.0000000000     5.4500028353     5.2651165536  5.4998048964E-4  2.7254270682E-4  7.3027600072E-5', 'G    18.0000000000     5.9500028353     5.6980908723  6.8625184136E-4  2.7254270682E-4  7.3027600072E-5']
_NUM = r'[-+]?\d*\.?\d+(?:[eE][-+]?\d+)?'


@pytest.mark.parametrize('name', ['sg2', 'sg3'])
def test_sol_geo_matches_gs(name):
    from pysad.ffscmd import run_sad_string
    buf = io.StringIO()
    run_sad_string(SRC[name], out=buf)
    got = [l.rstrip() for l in buf.getvalue().splitlines() if re.match(r'^ ?G ', l)]
    ref = REF[name]
    assert len(got) == len(ref) == 18
    for a, b in zip(got, ref):
        va = [float(v) for v in re.findall(_NUM, a[2:])]
        vb = [float(v) for v in re.findall(_NUM, b[2:])]
        for x, y in zip(va, vb):
            assert abs(x - y) <= 1e-9 * abs(y) + 1e-13, (a, b)
